#include "stdlib/blas/ext/base/ndarray/dcartesian_power.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "dcartesian-power"
#define ITERATIONS 100
#define REPEATS 3
#define MIN 1
#define MAX 3

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total ); // TAP plan
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations  number of iterations
* @param elapsed     elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec / 1.0e6;
}

/**
* Generates a random number on the interval [0,1).
*
* @return random number
*/
static double rand_double( void ) {
	int r = rand();
	return (double)r / ( (double)RAND_MAX + 1.0 );
}

/**
* Runs a benchmark.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds
*/
static double benchmark( int iterations, int len ) {
	enum STDLIB_NDARRAY_INDEX_MODE imode;
	const struct ndarray *arrays[ 3 ];
	enum STDLIB_NDARRAY_ORDER order;
	int8_t submodes1[ 1 ];
	int64_t strides1[ 1 ];
	int64_t shape1[ 1 ];
	int8_t submodes2[ 2 ];
	int64_t strides2[ 2 ];
	int64_t shape2[ 2 ];
	int8_t submodes3[ 1 ];
	int64_t strides3[ 1 ];
	int64_t nsubmodes;
	struct ndarray *x;
	struct ndarray *out;
	struct ndarray *k_arr;
	int64_t offset;
	double elapsed;
	int64_t ndims;
	double *data_x;
	double *data_out;
	int32_t *data_k;
	int32_t K = 2;
	double t;
	int i;

	ndims = 1;
	shape1[ 0 ] = len;
	strides1[ 0 ] = STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT;
	offset = 0;
	order = STDLIB_NDARRAY_ROW_MAJOR;
	imode = STDLIB_NDARRAY_INDEX_ERROR;
	submodes1[ 0 ] = imode;
	nsubmodes = 1;

	data_x = (double *)malloc( len * sizeof( double ) );
	for ( i = 0; i < len; i++ ) {
		data_x[ i ] = ( rand_double() * 200.0 ) - 100.0;
	}
	// cppcheck-suppress invalidPointerCast
	x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)data_x, ndims, shape1, strides1, offset, order, imode, nsubmodes, submodes1 );
	arrays[ 0 ] = x;

	ndims = 2;
	shape2[ 0 ] = (int64_t)pow( len, K );
	shape2[ 1 ] = K;
	strides2[ 1 ] = STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT;
	strides2[ 0 ] = K * STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT;
	offset = 0;
	submodes2[ 0 ] = imode;
	submodes2[ 1 ] = imode;
	nsubmodes = 2;

	data_out = (double *)malloc( shape2[0] * shape2[1] * sizeof( double ) );
	// cppcheck-suppress invalidPointerCast
	out = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)data_out, ndims, shape2, strides2, offset, order, imode, nsubmodes, submodes2 );
	arrays[ 1 ] = out;

	ndims = 0;
	offset = 0;
	nsubmodes = 1;
	submodes3[ 0 ] = imode;
	strides3[ 0 ] = 0;

	data_k = (int32_t *)malloc( sizeof( int32_t ) );
	data_k[ 0 ] = K;
	// cppcheck-suppress invalidPointerCast
	k_arr = stdlib_ndarray_allocate( STDLIB_NDARRAY_INT32, (uint8_t *)data_k, ndims, NULL, strides3, offset, order, imode, nsubmodes, submodes3 );
	arrays[ 2 ] = k_arr;

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		stdlib_blas_ext_dcartesian_power( arrays );
	}
	elapsed = tic() - t;

	stdlib_ndarray_free( x );
	stdlib_ndarray_free( out );
	stdlib_ndarray_free( k_arr );
	free( data_x );
	free( data_out );
	free( data_k );
	arrays[ 0 ] = NULL;
	arrays[ 1 ] = NULL;
	arrays[ 2 ] = NULL;

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	// Use the current time to seed the random number generator:
	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = MIN; i <= MAX; i++ ) {
		len = pow( 10, i );
		iter = ITERATIONS / pow( 10, i - 1 );
		if ( iter < 1 ) {
			iter = 1;
		}
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:len=%d\n", NAME, len );
			elapsed = benchmark( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
}
